import {decodePhones,PHONEME_MODEL} from './speech-core.js';
let model,vocab;
const base=`https://huggingface.co/${PHONEME_MODEL.id}/resolve/${PHONEME_MODEL.revision}/`;
async function cached(url){let cache;try{cache=await caches.open('mimora-phonemes-v1');const hit=await cache.match(url);if(hit)return hit.arrayBuffer();}catch{}const response=await fetch(url);if(!response.ok)throw Error(`Speech model download failed (${response.status}).`);const backup=response.clone(),reader=response.body.getReader(),chunks=[];let loaded=0;const total=Number(response.headers.get('content-length'))||355000000;while(true){const {done,value}=await reader.read();if(done)break;chunks.push(value);loaded+=value.length;self.postMessage({type:'progress',message:`Downloading pronunciation model: ${Math.min(100,Math.round(loaded/total*100))}%`});}const data=new Uint8Array(loaded);let at=0;for(const c of chunks){data.set(c,at);at+=c.length;}try{await cache?.put(url,backup);}catch{}return data.buffer;}
self.onmessage=async({data})=>{try{if(!model){self.postMessage({type:'progress',message:'Loading pronunciation model (first use: about 355 MB)…'});const ort=await import('https://cdn.jsdelivr.net/npm/onnxruntime-web@1.24.3/dist/ort.wasm.min.mjs');ort.env.wasm.numThreads=1;ort.env.wasm.proxy=false;ort.env.wasm.wasmPaths='https://cdn.jsdelivr.net/npm/onnxruntime-web@1.24.3/dist/';self.ort=ort;const vr=await fetch(base+'vocab.json');if(!vr.ok)throw Error('The pronunciation vocabulary could not load.');vocab=await vr.json();model=await ort.InferenceSession.create(await cached(base+'phonemes.onnx'),{executionProviders:['wasm'],graphOptimizationLevel:'all'});}
 const outputs=[];for(const [i,clip] of data.clips.entries()){self.postMessage({type:'progress',message:`Recognizing ${i===0?'expert':'your'} sounds…`});const tensor=new self.ort.Tensor('float32',clip.samples,[1,clip.samples.length]);const out=await model.run({input_values:tensor}),logits=Object.values(out)[0];outputs.push(decodePhones(logits.data,logits.dims[1],logits.dims[2],vocab,clip.offset,clip.duration));tensor.dispose();Object.values(out).forEach(t=>t.dispose());}self.postMessage({type:'result',phones:outputs});}catch(e){self.postMessage({type:'error',message:e.message});}};
